contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes an owner candidate, a recipient, and an amount to fund C with before the withdrawal attempt,
    // and a boolean indicating whether the test should attempt the withdraw as owner (true) or non-owner (false).
    function run(address ownerCandidate, address payable recipient, uint256 fundAmount, bool callAsOwner) public payable {
        require(address(this).balance >= fundAmount, "insufficient test balance");
        // The deployed contract C was constructed before this test with some owner; we can observe it.
        address initialOwner = c.owner();

        // Fund contract C by sending Ether from this contract to C
        // ensure we have enough balance in this contract (caller provided msg.value to deploy/run)
        // Transfer must be a top-level call that changes c's balance
        // Use call to transfer Ether to fallback of C
        (bool okFund,) = address(c).call{value: fundAmount}("");
        // funding may succeed or fail; still a valid observable

        uint256 beforeBalance = address(c).balance;

        bool reverted;
        // Decide who should call withdrawAll: if callAsOwner==true, we attempt to call as the known owner (if matches),
        // otherwise we call as this contract (which is caller for c). But we cannot impersonate arbitrary addresses.
        // So we implement: if callAsOwner==true and initialOwner==address(this), call directly (should succeed);
        // otherwise calling withdrawAll from this contract represents a non-owner call (may revert).
        // We capture whether it reverted and the post-balance.
        if (callAsOwner && initialOwner == address(this)) {
            // as owner
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // not owner (or we chose to act as non-owner)
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 afterBalance = address(c).balance;

        // General rule:
        // - If the call did not revert, then entire previous balance should have been transferred to recipient
        //   (so afterBalance == 0 and this contract's balance did not change because recipient is arbitrary;
        //    we can only check c's balance decreased to zero).
        // - If the call reverted, then contract balance must be unchanged.
        // Note: when call succeeds but beforeBalance==0, afterBalance==0 holds as well.
        assert(reverted ? afterBalance == beforeBalance : afterBalance == 0);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Run funds C with fundAmount (sent from this contract) then attempts withdrawAll to recipient.
    // It records whether withdrawAll reverted and asserts the invariant about C's balance.
    function run(address payable recipient, uint256 fundAmount) public payable {
        // ensure this test contract has enough balance to fund C
        require(address(this).balance >= fundAmount, "insufficient test balance");

        // Fund contract C by sending Ether to its fallback
        (bool fundOk,) = address(c).call{value: fundAmount}("");
        // record balance before withdraw attempt
        uint256 beforeBalance = address(c).balance;

        bool reverted;
        // Make the state-changing call to withdrawAll as a top-level statement and capture revert via try/catch
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = address(c).balance;

        // If the call reverted, balance must be unchanged; otherwise balance must be zero.
        assert(reverted ? afterBalance == beforeBalance : afterBalance == 0);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Send some funds into c, then attempt withdrawAll; assert owner unchanged and recipient gain equals decrease in c's balance when call succeeds.
    function run(address payable recipient, uint256 fundAmount) public payable {
        require(address(this).balance >= fundAmount, "insufficient test balance");

        // fund C by sending Ether to its fallback
        (bool okFund, ) = address(c).call{value: fundAmount}("");
        require(okFund, "funding failed");

        // observe before-values
        address beforeOwner = c.owner();
        uint256 beforeBalance = address(c).balance;
        uint256 beforeRecipientBalance = address(recipient).balance;

        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-values
        address afterOwner = c.owner();
        uint256 afterBalance = address(c).balance;
        uint256 afterRecipientBalance = address(recipient).balance;

        // If the call did not revert, owner must remain same and recipient's gain equals decrease in c's balance.
        assert(reverted || (afterOwner == beforeOwner && afterRecipientBalance - beforeRecipientBalance == beforeBalance - afterBalance));
    }

    receive() external payable {}
}

