contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address ownerCandidate, address payable recipient, uint deposit) public payable {
        require(address(this).balance >= deposit);
        // The freshly deployed c already has an owner set in its constructor (unknown here).
        // For the test we treat ownerCandidate as a candidate caller: we cannot change c.owner here.

        // Fund contract c with `deposit` wei from this test contract
        // ensure we have the funds and send
        if (deposit > 0) {
            // send Ether to c via its fallback
            payable(address(c)).transfer(deposit);
        }

        uint beforeC = address(c).balance;
        uint beforeRecipient = address(recipient).balance;
        address currentOwner = c.owner();

        bool reverted;
        // attempt withdrawAll as this contract by calling c.withdrawAll; but c expects msg.sender == owner
        // We need to call as InvMutTest (this contract). If this contract is the owner, the call should succeed.
        // If not, it should revert and balances unchanged.
        try c.withdrawAll{value:0}(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterC = address(c).balance;
        uint afterRecipient = address(recipient).balance;

        // General rule:
        // - If this contract is the owner of c, withdrawAll must succeed (not reverted), drain c to zero,
        //   and recipient's balance increases by exactly beforeC.
        // - If this contract is not the owner, withdrawAll must revert and both balances must remain equal to before-values.
        assert(
            (currentOwner == address(this) && !reverted && afterC == 0 && afterRecipient - beforeRecipient == beforeC)
            ||
            (currentOwner != address(this) && reverted && afterC == beforeC && afterRecipient == beforeRecipient)
        );
    }

    // allow this test contract to receive Ether for funding c
    receive() external payable {}
