contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test entry. params: caller address (as bytes20 to avoid address literal issues), recipient, amount sent to contract, and a flag whether to call withdraw as owner
    function run(address deployerOwner, address recipient, uint256 fundAmount, bool callAsOwner) public payable {
        require(address(this).balance >= fundAmount);

        // The C instance was deployed already with some owner (unknown here). We can observe owner via c.owner().
        address currentOwner = c.owner();

        // Fund contract c by sending Ether from this test contract
        if (fundAmount > 0) {
            // ensure we have funds and then send
            payable(address(c)).transfer(fundAmount);
        }

        // read balance before withdraw attempt
        uint256 beforeBalance = address(c).balance;

        // Decide whether to attempt withdraw as owner or not. If callAsOwner==true we attempt only when this contract is owner; otherwise attempt as non-owner.
        bool willCallAsOwner = callAsOwner;

        bool reverted;
        if (willCallAsOwner) {
            // Only proceed to call if this test contract is the owner; if not, calling would revert so we instead still test the revert behavior by calling as non-owner path below.
            if (currentOwner == address(this)) {
                reverted = false;
                try c.withdrawAll(recipient) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            } else {
                // Not owner: attempt call as non-owner to observe revert
                reverted = false;
                try c.withdrawAll(recipient) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            }
        } else {
            // explicit non-owner attempt: if this is owner, to ensure non-owner call we need to call from some other address, but we can't change msg.sender.
            // Instead we try calling and record revert; if this contract is owner the call will succeed, which violates the intended non-owner branch, so test's assertion will account for actual owner equality.
            reverted = false;
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 afterBalance = address(c).balance;

        // The general rule to assert:
        // - If the call did not revert, then C's balance must have decreased by exactly beforeBalance and afterBalance == 0, and recipient (an external address) should have received the funds (we cannot read recipient balance directly), so we assert afterBalance == 0 and that either beforeBalance==0 or the call did not revert.
        // - If the call reverted, balance must be unchanged.
        assert((!reverted && afterBalance == 0) || (reverted && afterBalance == beforeBalance));
    }

    receive() external payable { }
}

