    // params: recipient for withdraw, amount to fund C before withdraw, and a flag chooseCall which when true will attempt withdraw (always from this contract)
    function run(address recipient, uint256 fundAmount, bool chooseCall) public payable {
        require(address(this).balance >= fundAmount);

        // Fund contract c by sending Ether from this test contract
        if (fundAmount > 0) {
            payable(address(c)).transfer(fundAmount);
        }

        uint256 beforeBalance = address(c).balance;

        bool reverted;
        // Perform the withdrawAll call as a top-level statement (may revert)
        if (chooseCall) {
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // If not choosing to call, mark reverted=false and do nothing
            reverted = false;
        }

        uint256 afterBalance = address(c).balance;

        // General invariant: successful call -> contract balance becomes zero; reverted call -> balance unchanged; if no call made, balance unchanged
        assert((chooseCall && !reverted && afterBalance == 0) || ((chooseCall && reverted) || !chooseCall) && afterBalance == beforeBalance);
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: recipient for withdraw, amount to fund C before withdraw, and a flag doCall to decide whether to call withdrawAll
    function run(address recipient, uint256 fundAmount, bool doCall) public payable {
        require(address(this).balance >= fundAmount);

        // Fund contract c by sending Ether from this test contract
        if (fundAmount > 0) {
            payable(address(c)).transfer(fundAmount);
        }

        // read observable before-values
        address beforeOwner = c.owner();
        uint256 beforeBalance = address(c).balance;

        bool reverted;
        // Top-level state-changing call (or no call) as required
        if (doCall) {
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            reverted = false;
        }

        uint256 afterBalance = address(c).balance;
        address afterOwner = c.owner();

        // General rule:
        // - If we called and it succeeded (did not revert) then this contract must have been owner and contract's balance becomes zero.
        // - If we called and it reverted then either caller was not owner or the balance stayed the same.
        // - If we didn't call, owner and balance are unchanged.
        assert(
            // call performed and succeeded => owner was this contract and balance now zero
            (doCall && !reverted && beforeOwner == address(this) && afterBalance == 0) ||
            // call performed and reverted => (owner wasn't this) and balance unchanged, or revert for other reason but balance unchanged
            (doCall && reverted && afterBalance == beforeBalance) ||
            // no call => state unchanged
            (!doCall && afterBalance == beforeBalance && afterOwner == beforeOwner)
        );
    }

    receive() external payable { }
}

