    // single public test function with inputs:
    // - owner: address used when constructing c already (c is fresh and provided by harness)
    // - caller: address that will attempt to call withdrawAll (we simulate by having this contract call so we pass a flag whether to set msg.sender equal to owner by using owner parameter and relying on c.owner() observable)
    // - recipient: address to receive funds
    // - fundAmount: amount of wei to send into c before withdrawal
    function run(address caller, address payable recipient, uint256 fundAmount) public payable {
        require(true);
        // Ensure this test contract has enough balance to fund c when needed
        if (fundAmount > 0) {
            require(address(this).balance >= fundAmount, "insufficient balance to fund c");
            // send Ether to C by calling its fallback (external payable) using low-level call.
            (bool sent, ) = address(c).call{value: fundAmount}("");
            require(sent, "funding failed");
        }

        // Observe pre-state
        address ownerBefore = c.owner();
        uint256 balanceBefore = address(c).balance;

        // Decide whether to simulate owner call or non-owner call.
        // We cannot change msg.sender when calling c from this contract; msg.sender will always be this contract.
        // To cover both cases, we use two execution branches executed by the checker by varying 'caller' parameter:
        // If caller == ownerBefore then we treat this execution as the owner-invocation scenario; otherwise non-owner.

        bool reverted;
        // Attempt the call: since msg.sender is this contract, to simulate owner call we require that ownerBefore == address(this)
        // But we cannot change owner in c. The harness deploys c and may set owner to some address; we cannot impersonate it.
        // Therefore, instead of trying to change caller, we assert a general property that relates behavior for both possibilities
        // by observing whether the call reverts and comparing to owner getter.

        // Make the call and capture revert
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = address(c).balance;
        uint256 receivedByTest = address(this).balance; // may have increased if recipient == address(this)

        // General rule: withdrawAll can only succeed (not revert) when msg.sender equals c.owner(); in that case
        // the contract's balance must drop to zero and the recipient's balance must increase by the prior contract balance.
        // Since we cannot observe recipient balance directly unless recipient == address(this), we at least assert the balance invariant on c
        // and connect revert flag to owner equality.

        // Exactly one assert combining these facts:
        assert(
            // If the call did not revert then msg.sender (this contract) must be ownerBefore
            (!reverted && ownerBefore == address(this) && balanceAfter == 0 && balanceBefore >= balanceAfter)
            // If the call reverted then either msg.sender was not ownerBefore OR no change to c's balance occurred
            || (reverted && (ownerBefore != address(this)) && balanceAfter == balanceBefore)
        );
    }

    // allow receiving Ether when recipient==address(this)
    receive() external payable {}
}

