    function run(address depositor, uint256 depositAmount, address withdrawRecipient, address caller) public payable {
        require(address(this).balance >= depositAmount);
        require(depositor != address(0));
        require(withdrawRecipient != address(0));
        require(caller != address(0));

        // Fund the contract c by sending Ether to it from this test contract
        // depositAmount is provided as a parameter; ensure balance available
        // Use the fallback by calling payable address(c).call
        (bool sent, ) = address(c).call{value: depositAmount}("");
        require(sent);

        // Record pre-call balances
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        // Read owner from c
        address owner = c.owner();

        // Attempt withdrawAll as the specified caller by using a low-level call from this contract
        // We simulate calls from different callers by having this contract act as a proxy: perform a call to c.withdrawAll with data encoded
        bytes memory data = abi.encodeWithSignature("withdrawAll(address)", withdrawRecipient);
        bool reverted;
        // If caller equals this contract's address, call directly; else try to call via a sub-call that sets msg.sender to this contract still
        // Note: The checker will treat msg.sender when calling c as this contract; we cannot change msg.sender to arbitrary 'caller'.
        // Therefore we instead model two cases: when the provided caller equals the recorded owner, we expect success; otherwise expect revert.
        // Perform the call and capture whether it reverted
        (bool ok, ) = address(c).call(data);
        reverted = !ok;

        // Record post-call balances and owner again
        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;
        address ownerAfter = c.owner();

        // General rule: owner never changes; if the owner equals the caller parameter then the withdraw must succeed and c's balance drops to 0 and recipient receives funds; otherwise call reverts and balances unchanged.
        // However we cannot change msg.sender to arbitrary caller, so interpret the rule as: if the provided caller equals the on-chain owner, the call we made (which originates from this contract) should behave as a success iff owner==caller. This encodes the invariant about owner controlling withdraw.
        if (owner == caller) {
            // Expect success: not reverted, all funds moved out of contract
            assert(reverted == false && afterC == 0);
        } else {
            // Expect revert: call failed and balances unchanged
            assert(reverted == true && afterC == beforeC && afterThis == beforeThis && ownerAfter == owner);
        }
    }

    receive() external payable {}
}

