    // single public test entry
    function run(address initialOwner, address payable recipient, uint deposit) public payable {
        require(address(this).balance >= deposit);
        // Deploy-time owner already set in checker; we must not redeploy c. Instead, assert behavior relative to c.owner().
        // First, fund contract c with `deposit` wei from this test contract.
        if (deposit > 0) {
            // send Ether to c using its fallback
            (bool ok,) = address(c).call{value: deposit}("");
            require(ok);
        }

        uint256 beforeBalance = address(c).balance;
        address ownerAddr = c.owner();

        // Case A: call withdrawAll as owner -> should succeed and transfer entire balance to recipient
        bool ownerCallReverted;
        if (msg.sender == address(0)) { /* unreachable to avoid compiler warning about msg.sender usage */ }
        // We want to simulate calling as owner. The test contract is msg.sender when calling c, so only proceed with owner-path
        if (ownerAddr == address(this)) {
            // call as owner
            try c.withdrawAll(recipient) {
                ownerCallReverted = false;
            } catch {
                ownerCallReverted = true;
            }
            // After owner-successful call, the contract balance must be zero and recipient must have received the funds.
            // We can observe address(c).balance and address(this).balance; but recipient may be any address — we cannot read its balance unless it's this contract.
            // To assert observable transfer, require recipient==address(this) in the owner path; otherwise assert that either call reverted or c.balance is zero.
            if (recipient == payable(address(this))) {
                // If recipient is this contract, its balance should increase by beforeBalance when call succeeded.
                if (!ownerCallReverted) {
                    assert(address(c).balance == 0 && address(this).balance >= beforeBalance);
                } else {
                    // if reverted, balance unchanged
                    assert(address(c).balance == beforeBalance);
                }
            } else {
                // For other recipients, assert: if call didn't revert then c.balance == 0; if reverted then unchanged
                if (!ownerCallReverted) {
                    assert(address(c).balance == 0);
                } else {
                    assert(address(c).balance == beforeBalance);
                }
            }
            return;
        }

        // Case B: call withdrawAll as non-owner -> must revert and balance unchanged.
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General assert: if caller (this contract) is not the owner, withdrawAll must revert and contract balance must stay the same.
        assert((ownerAddr != address(this)) ? (reverted && address(c).balance == beforeBalance) : true);
    }

    receive() external payable {}
}

