contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address payable initialOwner, address payable caller, address payable recipient, uint256 deposit) public payable {
        require(address(this).balance >= deposit);
        // We assume the freshly deployed c already has owner set in its constructor.
        // First, record current owner and balances.
        address beforeOwner = c.owner();
        uint256 cBalBefore = address(c).balance;
        uint256 recipBalBefore = recipient.balance;

        // If we want to simulate calling withdrawAll from either the owner or not, we need to have this contract
        // be the caller to c. But the checker deploys c with InvMutTest as msg.sender, so to test both cases
        // we will attempt the withdraw via this contract; to simulate owner situation we require that `caller`
        // equals address(this) when we want owner-case; otherwise non-owner.
        // We do not perform external calls from arbitrary accounts, so we model both possibilities by first
        // checking whether this contract is the owner according to c.owner(). If not equal, then a withdraw
        // from this contract should revert; if equal, it should succeed.

        bool reverted;
        // Attempt withdrawAll from this contract (msg.sender == address(this)).
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After attempt, read balances and owner again
        address afterOwner = c.owner();
        uint256 cBalAfter = address(c).balance;
        uint256 recipBalAfter = recipient.balance;

        // General rule:
        // - The owner value never changes due to withdrawAll (withdrawAll does not alter owner).
        // - If the call did not revert, then c's balance became zero and recipient's balance increased by the exact amount withdrawn (cBalBefore).
        // - If the call reverted, then balances remain unchanged.
        assert(
            // owner unchanged
            afterOwner == beforeOwner
            // either successful withdraw: reverted==false implies c balance zero and recipient increased by cBalBefore
            && ( (!reverted && cBalAfter == 0 && recipBalAfter == recipBalBefore + cBalBefore)
                 // or failed withdraw: reverted==true implies balances unchanged
                 || (reverted && cBalAfter == cBalBefore && recipBalAfter == recipBalBefore) )
        );
    }

    // allow receiving ETH if needed
    receive() external payable {}
}

